public class ReplaySession {
    private static final Logger LOGGER = Logger.getLogger("ReplaySession");
    private final UUID playerUUID;
    private final String sessionName;
    private final ReplayBuffer buffer;
    private final ReplayWriter writer;
    private final ScheduledExecutorService scheduler;
    private boolean recording;

    public ReplaySession(UUID playerUUID, String sessionName) {
        this.playerUUID = playerUUID;
        this.sessionName = sessionName;
        this.buffer = new ReplayBuffer();
        this.writer = new BinaryReplayWriter();
        this.scheduler = Executors.newSingleThreadScheduledExecutor();
    }

    public void start() {
        LOGGER.info("[DEBUG] Starting session: " + sessionName + " for " + playerUUID);
        this.writer.initialize(sessionName);
        this.recording = true;

        scheduler.scheduleAtFixedRate(() -> {
            try {
                if (recording) {
                    var flushed = buffer.flush();
                    if (!flushed.isEmpty()) {
                        LOGGER.info("[DEBUG] Session " + sessionName + ": Flushing " + flushed.size() + " frames to disk.");
                        writer.writeFrames(flushed);
                    }
                }
            } catch (Exception e) {
                LOGGER.severe("[DEBUG] Error during flush for " + sessionName + ": " + e.getMessage());
                e.printStackTrace();
            }
        }, 1, 1, TimeUnit.SECONDS);
    }

    public void stop() {
        LOGGER.info("[DEBUG] Stopping session: " + sessionName);
        this.recording = false;
        scheduler.shutdown();
        writer.close();
    }

    public void addFrame(fr.lampalon.lifemod.common.replay.packet.ReplayFrame frame) {
        if (recording) {
            buffer.addFrame(frame);
        } else {
            LOGGER.warning("[DEBUG] Attempted to add frame to session " + sessionName + " but recording is false.");
        }
    }

    public UUID getPlayerUUID() {
        return playerUUID;
    }

    public String getSessionName() {
        return sessionName;
    }

    public boolean isRecording() {
        return recording;
    }
}

package fr.lampalon.lifemod.common.replay.buffer;

import fr.lampalon.lifemod.common.replay.packet.ReplayFrame;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.ArrayList;
import java.util.List;

/**
 * Thread-safe buffer for incoming replay frames to maintain performance.
 */
public class ReplayBuffer {

    private final ConcurrentLinkedQueue<ReplayFrame> frameQueue = new ConcurrentLinkedQueue<>();

    /**
     * Appends a frame to the queue.
     * @param frame The frame to record.
     */
    public void addFrame(ReplayFrame frame) {
        frameQueue.add(frame);
    }

    /**
     * Drains the queue for asynchronous processing.
     * @return List of current recorded frames.
     */
    public List<ReplayFrame> flush() {
        List<ReplayFrame> flushedFrames = new ArrayList<>();
        ReplayFrame frame;
        while ((frame = frameQueue.poll()) != null) {
            flushedFrames.add(frame);
        }
        return flushedFrames;
    }

    /**
     * Returns the current size of the buffer.
     * @return Current buffer size.
     */
    public int size() {
        return frameQueue.size();
    }
}

package fr.lampalon.lifemod.common.replay.storage;

import fr.lampalon.lifemod.common.replay.packet.ReplayFrame;
import java.io.*;
import java.util.List;
import java.util.logging.Logger;

/**
 * Implementation of ReplayWriter using binary format for storage.
 */
public class BinaryReplayWriter implements ReplayWriter {

    private static final Logger LOGGER = Logger.getLogger("BinaryReplayWriter");
    private DataOutputStream outputStream;
    private File sessionFile;

    @Override
    public void initialize(String sessionName) {
        File replayDir = new File("plugins/LifeMod/replays");
        if (!replayDir.exists()) {
            replayDir.mkdirs();
        }
        this.sessionFile = new File(replayDir, sessionName + ".replay");
        try {
            this.outputStream = new DataOutputStream(new BufferedOutputStream(new FileOutputStream(sessionFile)));
            LOGGER.info("[DEBUG] Initialized writer for file: " + sessionFile.getAbsolutePath());
        } catch (IOException e) {
            LOGGER.severe("[DEBUG] Failed to initialize writer for " + sessionName + ": " + e.getMessage());
            e.printStackTrace();
        }
    }

    @Override
    public void writeFrames(List<ReplayFrame> frames) {
        if (outputStream == null) {
            LOGGER.warning("[DEBUG] writeFrames called but outputStream is null!");
            return;
        }
        try {
            int packetTotal = 0;
            for (ReplayFrame frame : frames) {
                outputStream.writeLong(frame.getTimestamp());
                outputStream.writeInt(frame.getPackets().size());
                for (byte[] packetData : frame.getPackets()) {
                    outputStream.writeInt(packetData.length);
                    outputStream.write(packetData);
                    packetTotal++;
                }
            }
            outputStream.flush();
            LOGGER.info("[DEBUG] Wrote " + frames.size() + " frames (" + packetTotal + " packets) to " + sessionFile.getName());
        } catch (IOException e) {
            LOGGER.severe("[DEBUG] Error writing frames to " + sessionFile.getName() + ": " + e.getMessage());
            e.printStackTrace();
        }
    }

    @Override
    public void close() {
        if (outputStream != null) {
            try {
                outputStream.close();
                LOGGER.info("[DEBUG] Closed writer for " + sessionFile.getName() + ". Final size: " + sessionFile.length() + " bytes.");
            } catch (IOException e) {
                LOGGER.severe("[DEBUG] Error closing writer for " + sessionFile.getName() + ": " + e.getMessage());
                e.printStackTrace();
            }
        }
    }
}

