import fr.lampalon.lifemod.common.core.ILifePlatform;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.scheduler.BukkitRunnable;

import java.util.List;
import java.util.UUID;
import java.util.logging.Logger;

/**
 * Manages the playback of recorded replay data using dedicated replay tools.
 */
public class PlaybackManager {
    private static final Logger LOGGER = Logger.getLogger("PlaybackManager");
    private final LifeMod plugin;
    private final EntityIdMapper idMapper;
    private final SkinManager skinManager;
    private List<ReplayFrame> frames;
    private int currentIndex = 0;
    private int virtualId = -1;
    private UUID npcUUID;

    public PlaybackManager(LifeMod plugin) {
        this.plugin = plugin;
        this.idMapper = new EntityIdMapper();
        this.skinManager = new SkinManager();
    }

    /**
     * Starts replaying captured frames to a spectator.
     * @param spectator The mod viewing the replay.
     * @param frames The frames to play.
     */
    public void startPlayback(Player spectator, List<ReplayFrame> frames) {
        this.frames = frames;
        this.currentIndex = 0;
        this.npcUUID = UUID.randomUUID();

        // We need the original entity ID to map it. 
        // For simplicity, let's assume the first frame might contain it or we pass it.
        // But we already have the ReplaySession in the command. 
        // Let's modify the signature to accept more info.
    }

    // Revised startPlayback
    public void startPlayback(Player spectator, List<ReplayFrame> frames, int originalEntityId, String playerName, UUID playerUUID) {
        this.frames = frames;
        this.currentIndex = 0;
        this.npcUUID = UUID.randomUUID();
        this.virtualId = idMapper.getVirtualId(originalEntityId);

        LOGGER.info("[DEBUG] Starting playback for spectator " + spectator.getName());
        LOGGER.info("[DEBUG] NPC Name: " + playerName + ", Virtual ID: " + virtualId + ", Frames: " + frames.size());

        NMSReplayHandler nms = (NMSReplayHandler) ServiceRegistry.get(ILifePlatform.class).getNmsProvider();

        // Spawn NPC initially at spectator's location or first frame location if possible
        nms.spawnNPC(spectator, npcUUID, playerName, spectator.getLocation());

        new BukkitRunnable() {
            @Override
            public void run() {
                if (currentIndex >= frames.size()) {
                    LOGGER.info("[DEBUG] Playback finished for " + spectator.getName());
                    nms.removeNPC(spectator, npcUUID);
                    this.cancel();
                    idMapper.clear();
                    return;
                }

                ReplayFrame frame = frames.get(currentIndex);
                List<byte[]> packets = frame.getPackets();

                for (byte[] data : packets) {
                    // Here is the tricky part: re-sending raw packets.
                    // PacketEvents doesn't easily allow sending raw byte[] as a packet without a type.
                    // We should have recorded the packet type too.

                    // For now, let's just log that we are "playing" it
                    // To actually see something, we need to send move packets etc.
                }

                currentIndex++;

                if (currentIndex % 100 == 0) {
                    LOGGER.info("[DEBUG] Playback progress: " + currentIndex + "/" + frames.size());
                }
            }
        }.runTaskTimer(plugin, 0L, 1L);
    }
}

