package fr.lampalon.lifemod.platform.bukkit.replay;

import com.github.retrooper.packetevents.PacketEvents;
import com.github.retrooper.packetevents.netty.buffer.ByteBufHelper;
import com.github.retrooper.packetevents.protocol.player.TextureProperty;
import fr.lampalon.lifemod.common.nms.api.NMSReplayHandler;
import fr.lampalon.lifemod.common.replay.EntityIdMapper;
import fr.lampalon.lifemod.common.replay.SkinManager;
import fr.lampalon.lifemod.common.replay.packet.ReplayFrame;
import fr.lampalon.lifemod.platform.bukkit.LifeMod;
import fr.lampalon.lifemod.common.core.ServiceRegistry;
import fr.lampalon.lifemod.common.core.ILifePlatform;
import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.entity.Player;
import org.bukkit.scheduler.BukkitRunnable;

import java.util.List;
import java.util.UUID;
import java.util.logging.Logger;

/**
 * Manages the playback of recorded replay data.
 */
public class PlaybackManager {
    private static final Logger LOGGER = Logger.getLogger("PlaybackManager");
    private final LifeMod plugin;
    private final EntityIdMapper idMapper;
    private List<ReplayFrame> frames;
    private int currentIndex = 0;
    private UUID npcUUID;

    public PlaybackManager(LifeMod plugin) {
        this.plugin = plugin;
        this.idMapper = new EntityIdMapper();
    }

    public void startPlayback(Player spectator, List<ReplayFrame> frames, int originalEntityId, String playerName, UUID playerUUID) {
        this.frames = frames;
        this.currentIndex = 0;
        this.npcUUID = UUID.randomUUID();

        LOGGER.info("[DEBUG] Starting playback for " + spectator.getName() + ". Frames: " + frames.size());

        NMSReplayHandler nms = (NMSReplayHandler) ServiceRegistry.get(ILifePlatform.class).getNmsProvider();

        // Get skin from SkinManager
        TextureProperty[] skin = plugin.getReplayManager().getSkinManager().getSkin(playerUUID);
        if (skin != null) {
            LOGGER.info("[DEBUG] Found skin for " + playerName);
        } else {
            LOGGER.info("[DEBUG] No skin found for " + playerName + ", using default.");
        }

        // Use the original entity ID for the NPC to match the recorded packets!
        // (This works as long as the real player is hidden from the spectator)
        // Let's spawn the NPC at the spectator's current location initially
        nms.spawnNPC(spectator, npcUUID, playerName, skin, spectator.getLocation());

        // Hide the real player from the spectator to avoid conflicts if they are nearby
        Player realPlayer = Bukkit.getPlayer(playerUUID);
        if (realPlayer != null && realPlayer.isOnline()) {
            spectator.hidePlayer(plugin, realPlayer);
        }

        new BukkitRunnable() {
            @Override
            public void run() {
                if (currentIndex >= frames.size()) {
                    LOGGER.info("[DEBUG] Replay finished.");
                    nms.removeNPC(spectator, npcUUID);
                    if (realPlayer != null && realPlayer.isOnline()) {
                        spectator.showPlayer(plugin, realPlayer);
                    }
                    this.cancel();
                    return;
                }

                ReplayFrame frame = frames.get(currentIndex);
                for (byte[] data : frame.getPackets()) {
                    try {
                        // We send the raw packet bytes back to the spectator.
                        // Since we spawned the NPC with the original UUID/ID logic, 
                        // the client should associate these packets with the NPC.

                        // ByteBuf b = Unpooled.wrappedBuffer(data);
                        // PacketEvents.getAPI().getProtocolManager().sendPacket(spectator, b);

                        // Actually PacketEvents v2 uses a different way to send raw:
