        if (realPlayer != null && realPlayer.isOnline()) {
            spectator.hidePlayer(plugin, realPlayer);
        }

        new BukkitRunnable() {
            @Override
            public void run() {
                if (currentIndex >= frames.size()) {
                    LOGGER.info("[DEBUG] Replay finished for " + spectator.getName());
                    nms.removeNPC(spectator, npcUUID);
                    if (realPlayer != null && realPlayer.isOnline()) {
                        spectator.showPlayer(plugin, realPlayer);
                    }
                    this.cancel();
                    return;
                }

                ReplayFrame frame = frames.get(currentIndex);
                for (byte[] data : frame.getPackets()) {
                    try {
                        // Send raw packet to spectator using Netty Unpooled buffer
                        PacketEvents.getAPI().getProtocolManager().sendPacket(spectator, 
                            io.netty.buffer.Unpooled.wrappedBuffer(data));
                    } catch (Exception e) {
                        // Ignore individual packet errors
                    }
                }

                currentIndex++;

                if (currentIndex % 200 == 0) {
                    spectator.sendMessage("§7Replay progress: " + (int)((currentIndex/(double)frames.size())*100) + "%");
                }
            }
        }.runTaskTimer(plugin, 0L, 1L);
    }
}

package fr.lampalon.lifemod.common.nms.api;

import org.bukkit.entity.Player;

/**
 * Interface representing NMS (net.minecraft.server) capabilities.
 * This abstraction layer allows the plugin to be compatible with multiple Minecraft versions.
 * 
 * Règle : Aucune importation net.minecraft ou org.bukkit.craftbukkit ne doit figurer ici.
 */
public interface NMSProvider {

    /**
     * Sends an action bar message to a player.
     *
     * @param player  The player receiving the message.
     * @param message The message to display.
     */
    void sendActionBar(Player player, String message);

    /**
     * Sends a title and subtitle to a player.
     *
     * @param player   The player receiving the title.
     * @param title    The title text.
     * @param subtitle The subtitle text.
     * @param fadeIn   The fade in time in ticks.
     * @param stay     The stay time in ticks.
     * @param fadeOut  The fade out time in ticks.
     */
    void sendTitle(Player player, String title, String subtitle, int fadeIn, int stay, int fadeOut);

    /**
     * Kicks a player with a custom reason.
     *
     * @param player The player to kick.
     * @param reason The reason for the kick.
     */
    void kickPlayer(Player player, String reason);

    /**
     * Retrieves the ping of a player.
     *
     * @param player The player.
     * @return The ping in milliseconds.
     */
    int getPing(Player player);

    /**
     * Retrieves the name of this NMS version.
     *
     * @return The NMS version name.
     */
    String getName();
}

